import React, { useContext } from 'react';
import { Link } from 'react-router-dom';
import { GraduationCap, Languages } from 'lucide-react';
import { AuthContext } from '../context/AuthContext';
import { LanguageContext } from '../context/LanguageContext';

const Navbar = () => {
  const { isAuthenticated, user, logout } = useContext(AuthContext);
  const { language, toggleLanguage } = useContext(LanguageContext);

  return (
    <nav className="relative flex justify-between items-center px-8 py-5 bg-[#0A0E1A]/95 backdrop-blur-md border-b border-slate-800/60 sticky top-0 z-50">
      <div className="absolute bottom-0 left-0 right-0 h-px bg-gradient-to-r from-transparent via-blue-500/50 to-transparent"></div>

      <Link to="/" className="flex items-center gap-3 group">
        <div className="relative">
          <div className="absolute inset-0 bg-blue-400 blur-md opacity-40 group-hover:opacity-70 transition-opacity rounded-sm"></div>
          <div className="relative w-3 h-3 rounded-sm bg-gradient-to-br from-blue-400 via-cyan-400 to-blue-500 rotate-45 group-hover:rotate-[135deg] transition-transform duration-500 shadow-lg shadow-blue-500/50"></div>
        </div>
        <span className="text-lg font-extrabold tracking-[0.08em] text-white">
          GUARDIAN <span className="bg-gradient-to-r from-blue-400 to-cyan-300 bg-clip-text text-transparent font-black">CYBER LABS</span>
        </span>
      </Link>

      <div className="flex gap-3 items-center">
        <button
          onClick={toggleLanguage}
          className="flex items-center gap-1.5 text-xs font-bold text-slate-300 hover:text-white border border-slate-700 hover:border-slate-500 px-3 py-2 rounded-lg transition-colors"
        >
          <Languages size={14} />
          {language === 'fr' ? 'FR' : 'EN'}
        </button>

        <Link to="/about" className="flex items-center gap-2 text-sm font-semibold text-blue-400 border border-blue-500/30 bg-blue-500/5 hover:bg-blue-500/15 hover:border-blue-400/60 hover:shadow-lg hover:shadow-blue-500/20 px-4 py-2 rounded-lg transition-all duration-300 hidden sm:flex">
          <GraduationCap size={16} />
          {language === 'fr' ? "L'Académie" : 'Academy'}
        </Link>

        {!isAuthenticated ? (
          <Link
            to="/login"
            className="relative overflow-hidden bg-gradient-to-r from-blue-600 to-cyan-500 hover:from-blue-500 hover:to-cyan-400 text-white text-sm font-semibold px-5 py-2.5 rounded-lg transition-all shadow-md shadow-blue-600/30 hover:shadow-lg hover:shadow-blue-500/40"
          >
            {language === 'fr' ? 'Connexion' : 'Log in'}
          </Link>
        ) : (
          <>
            {user?.role === 'admin' && (
              <Link to="/admin" className="text-sm font-semibold text-blue-400 hover:text-blue-300 px-4 py-2 rounded-lg hover:bg-blue-500/10 transition-colors">
                Console Admin
              </Link>
            )}
            <Link to="/dashboard" className="text-sm font-semibold text-slate-300 hover:text-white px-4 py-2 rounded-lg hover:bg-slate-800/60 transition-colors">
              {language === 'fr' ? 'Mon Apprentissage' : 'My Learning'}
            </Link>
            <Link to="/profile" className="text-sm font-semibold text-slate-300 hover:text-white px-4 py-2 rounded-lg hover:bg-slate-800/60 transition-colors">
              {language === 'fr' ? 'Mon Profil' : 'My Profile'}
            </Link>
            <button onClick={logout} className="text-sm font-semibold text-red-400 hover:text-red-300 px-4 py-2 rounded-lg hover:bg-red-500/10 transition-colors">
              {language === 'fr' ? 'Déconnexion' : 'Log out'}
            </button>
            <div className="w-9 h-9 rounded-full bg-gradient-to-br from-slate-700 to-slate-800 border border-slate-600 flex items-center justify-center text-xs font-bold text-white">
              {user?.email?.[0]?.toUpperCase() || 'U'}
            </div>
          </>
        )}
      </div>
    </nav>
  );
};
export default Navbar;
